// Obtener jsPDF desde la librería cargada en el navegador
const { jsPDF } = window.jspdf;
/**
 * ==========================================================================
 * ARCHIVO DE CONFIGURACIÓN DE FUENTES
 * ==========================================================================
 * Este archivo es el "motor de tipografías" de el sistema. Se encarga de:
 * 1. Almacenar los códigos Base64 de las fuentes personalizadas.
 * 2. Limpiar esos códigos para evitar errores de sintaxis (espacios, basura).
 * 3. Inyectar las fuentes en el navegador para la "Vista Previa" (CSS dinámico).
 * 4. Registrar las fuentes en jsPDF para que funcionen al descargar el PDF.
 *
 * IMPORTANTE: Los nombres registrados aquí deben coincidir EXACTAMENTE 
 * con las opciones del menú desplegable de HTML o React.
 */

// ==========================================================================
// 1. DICCIONARIO DE FUENTES (BASE64)
// ==========================================================================
// Aquí se guardan las fuentes convertidas. 
const fonts = {
  //  Base64 de Arial Narrow 
  arialNarrow: "",
  
  // Base 64 de calibri Light, Las comillas invertidas evitan que el código falle si hay saltos de línea.
  calibriLight: ``,
 
  // Pega aquí el Base64 de Roboto
  calibri: ``,

  arial: ``,

  arialRounded:  ``,

  bahnschrift: ``

};

/**
 * ==========================================================================
 * FUNCIÓN: INYECTAR WEB (VISTA PREVIA EN PANTALLA)
 * ==========================================================================
 * Toma el código Base64 y crea una regla CSS (@font-face) dinámicamente.
 * Esto permite que la letra cambie de forma visual en la web antes de descargar.
 */
const inyectarWeb = (nombre, b64) => {
  if (!b64 || b64.length < 500) return;
  
  // Limpiamos el código: quita el '2' inicial, espacios y encabezados
  const limpia = b64.trim()
    .replace(/^data:font\/ttf;base64,/, '')
    .replace(/^2/, '')
    .replace(/\s/g, '');
  
  // Evitar duplicados: verificamos si la fuente ya fue inyectada en el HTML antes
  const id = `web-font-${nombre.replace(/\s+/g, '-')}`;
  if (document.getElementById(id)) return;

   // Creamos una etiqueta <style> y le metemos la regla @font-face
  const style = document.createElement('style');
  style.id = id;
  style.innerHTML = `
    @font-face { 
      font-family: '${nombre}'; 
      src: url(data:font/ttf;base64,${limpia}) format('truetype'); 
      font-weight: normal;
      font-style: normal;
    }
  `;

  // La agregamos al <head> de la página web para que haga efecto instantáneo
  document.head.appendChild(style);
  console.log(`✨ Fuente inyectada visualmente: ${nombre}`);
};

/**
 * ==========================================================================
 *  FUNCIÓN: REGISTRAR FUENTES EN JSPDF (DESCARGA DEL PDF)
 * ==========================================================================
 * Esta función se "conecta" a los eventos internos de jsPDF. Cuando se crea 
 * un nuevo documento PDF, jsPDF ejecuta esta función para cargar las letras.
 */
const callAddFonts = function () {
   // Función de limpieza similar a la de web, pero exclusiva para jsPDF
  const limpiar = (str) => {
    if (!str) return null;
    return str.trim()
      .replace(/^data:font\/ttf;base64,/, '')
      .replace(/^2/, '')
      .replace(/\s/g, '');
  };

   // REGISTRO DE FUENTES:
  // - addFileToVFS: Guarda el archivo virtualmente en la memoria del PDF.
  // - addFont: Le dice al PDF cómo se llama la fuente para usarla con setFont().
  
  if (fonts.calibriLight && fonts.calibriLight.length > 100) {
    this.addFileToVFS("CalibriLight", limpiar(fonts.calibriLight));
    this.addFont("CalibriLight", "CalibriLight", "normal");
  }

  if (fonts.calibri && fonts.calibri.length > 100) {
    this.addFileToVFS("Calibri", limpiar(fonts.calibri));
    this.addFont("Calibri", "Calibri", "normal");
  }

  if (fonts.arial && fonts.arial.length > 100) {
    this.addFileToVFS("Arial", limpiar(fonts.arial));
    this.addFont("Arial", "Arial", "normal");
  }

  if (fonts.arialNarrow && fonts.arialNarrow.length > 100) {
   this.addFileToVFS("ArialNarrow", limpiar(fonts.arialNarrow)); 
    this.addFont("ArialNarrow", "ArialNarrow", "normal");
  }

  if (fonts.arialRounded && fonts.arialRounded.length > 100) {
    this.addFileToVFS("ArialRounded", limpiar(fonts.arialRounded));
   this.addFont("ArialRounded", "ArialRounded", "normal");
  }

  if (fonts.bahnschrift && fonts.bahnschrift.length > 100) {
    this.addFileToVFS("Bahnschrift", limpiar(fonts.bahnschrift));
   this.addFont("Bahnschrift", "Bahnschrift", "normal");
  }
};

/**
 * ==========================================================================
 *  INICIALIZACIÓN AUTOMÁTICA
 * ==========================================================================
 * Esta función es el "arranque" del sistema. Se ejecuta sola al cargar.
 */
const inicializar = () => {
 // 1. Instalar las fuentes en la pantalla web (para la vista previa)
 inyectarWeb("CalibriLight", fonts.calibriLight);
  inyectarWeb("Calibri", fonts.calibri);
  inyectarWeb("Arial", fonts.arial);
  inyectarWeb("ArialNarrow", fonts.arialNarrow);
  inyectarWeb("ArialRounded", fonts.arialRounded);
  inyectarWeb("Bahnschrift", fonts.bahnschrift);

// 2. Conectar las fuentes a la librería jsPDF
  if (jsPDF && jsPDF.API) {
    // Si jsPDF ya está listo, agregamos las fuentes a su evento de inicio
    jsPDF.API.events.push(["addFonts", callAddFonts]);
    console.log("✅ Sistema de fuentes sincronizado para Web y PDF");
  } else {
    // Si jsPDF AÚN NO CARGA (porque el internet está lento o la librería pesa),
    // espera una fracción de segundo (100ms) y vuelve a intentar conectarse.
    setTimeout(inicializar, 100);
  }
};
// Arrancar el motor en cuanto se lee el archivo
inicializar();